import{_ as e,o as t,c as i,a0 as l}from"./chunks/framework.CI7OaYtj.js";const u=JSON.parse('{"title":"App 专题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/app.md","filePath":"guide/app.md"}'),d={name:"guide/app.md"};function o(p,a,s,n,r,c){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="app-专题" tabindex="-1">App 专题 <a class="header-anchor" href="#app-专题" aria-label="Permalink to &quot;App 专题&quot;">​</a></h1><p>uni-app X 的 App 端有两种渲染模式，项目默认使用 Vapor，并兼容 VDOM。</p><table tabindex="0"><thead><tr><th style="text-align:left;">模式</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;">Vapor</td><td style="text-align:left;">无虚拟 DOM，原生渲染性能更好，项目默认</td></tr><tr><td style="text-align:left;">VDOM</td><td style="text-align:left;">传统虚拟 DOM，适合兼容旧组件或排查问题时切换</td></tr></tbody></table><p>切换入口在 <code>manifest.config.ts</code> / <code>manifest.json</code> 的 <code>vapor</code> 配置。不要长期同时维护两套业务写法。</p><h2 id="app-开发环境" tabindex="-1">App 开发环境 <a class="header-anchor" href="#app-开发环境" aria-label="Permalink to &quot;App 开发环境&quot;">​</a></h2><ul><li>HBuilderX 5.26+</li><li>Android：JDK 17、Android SDK</li><li>iOS：macOS、Xcode</li><li>鸿蒙：DevEco Studio</li></ul><p>CLI 命令仍依赖本机正在运行的 HBuilderX。</p><h2 id="原生能力" tabindex="-1">原生能力 <a class="header-anchor" href="#原生能力" aria-label="Permalink to &quot;原生能力&quot;">​</a></h2><ul><li>相机、扫码、文件、设备信息等能力优先使用 uni-app X 官方 API。</li><li>引入原生插件前确认 Android / iOS / 鸿蒙支持矩阵。</li><li>需要原生 jar 或收费插件时，必须准备自定义基座，不能使用标准基座验证。</li><li>端专属符号必须使用条件编译隔离，不能只在普通 <code>if</code> 中判断。</li></ul><h2 id="配置与权限" tabindex="-1">配置与权限 <a class="header-anchor" href="#配置与权限" aria-label="Permalink to &quot;配置与权限&quot;">​</a></h2><p><code>manifest.json</code> 由 <code>manifest.config.ts</code> 生成。修改 AppID、权限、图标、版本号和原生模块后，应同步源配置，避免下一次构建被覆盖。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest</span></span></code></pre></div><h2 id="真机排查顺序" tabindex="-1">真机排查顺序 <a class="header-anchor" href="#真机排查顺序" aria-label="Permalink to &quot;真机排查顺序&quot;">​</a></h2><ol><li>先跑 Android，UTS 类型与 Kotlin 编译最严格。</li><li>清理 <code>unpackage</code> 后重新编译，排除旧缓存。</li><li>检查是否出现循环依赖、端专属 API 裸调用或错误的条件编译。</li><li>使用日志定位到具体页面和生命周期，不做盲目重试。</li></ol>',14)])])}const f=e(d,[["render",o]]);export{u as __pageData,f as default};
